h1, h2, h3, h4 {
  margin-top: 0;
  color: #ffffff;
}

h1 { font-size: 2.5rem; }
h2 { font-size: 2rem; margin-bottom: var(--spacing-lg); }
h3 { font-size: 1.25rem; margin-bottom: var(--spacing-sm); }

p { margin-bottom: var(--spacing-md); }

/* Layout */
.container {
  max-width: var(--container-max-width);
  margin: 0 auto;
  padding: 0 var(--spacing-md);
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border-width: 0;
}

.skip-link {
  position: absolute;
  top: -100px;
  left: 0;
  background: var(--color-primary);
  color: var(--color-on-primary);
  padding: var(--spacing-sm) var(--spacing-md);
  z-index: 100;
  text-decoration: none;
  font-weight: bold;
}

.skip-link:focus {
  top: 0;
}

/* Header */
header {
  border-bottom: 1px solid var(--color-border);
  padding: var(--spacing-md) 0;
  background-color: var(--color-bg);
  position: sticky;
  top: 0;
  z-index: 50;
}

header .container {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: var(--spacing-md);
}

.logo {
  font-size: 1.5rem;
  font-weight: bold;
  text-decoration: none;
  color: var(--color-primary);
}

nav[aria-label="Primary"] ul {
  display: flex;
  list-style: none;
  margin: 0;
  padding: 0;
  gap: var(--spacing-md);
}

nav[aria-label="Primary"] a {
  color: var(--color-text);
  text-decoration: none;
  font-weight: 500;
  padding: var(--spacing-xs) var(--spacing-sm);
  border-radius: 4px;
}

nav[aria-label="Primary"] a:hover {
  background-color: var(--color-surface);
}

nav[aria-label="Primary"] a[aria-current="page"] {
  color: var(--color-primary);
  border-bottom: 2px solid var(--color-primary);
}

.header-actions {
  display: flex;
  gap: var(--spacing-sm);
}

.btn-icon {
  background: none;
  border: none;
  color: var(--color-text);
  cursor: pointer;
  padding: var(--spacing-sm);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: background-color 0.2s;
}

.btn-icon:hover {
  background-color: var(--color-surface);
}

.btn-icon svg {
  width: 24px;
  height: 24px;
  fill: currentColor;
}

/* Main */
main:focus {
  outline: none;
}

/* Hero */
.hero {
  padding: var(--spacing-xl) 0;
  background: linear-gradient(rgba(0,0,0,0.6), rgba(0,0,0,0.6)), url('https://images.unsplash.com/photo-1441986300917-64674bd600d8?auto=format&fit=crop&w=1200&q=80');
  background-size: cover;
  background-position: center;
  text-align: center;
  border-radius: 8px;
  margin: var(--spacing-lg) 0;
}

.hero-content {
  max-width: 600px;
  margin: 0 auto;
}

.hero h1 {
  margin-bottom: var(--spacing-md);
}

.btn-primary {
  display: inline-block;
  background-color: var(--color-primary);
  color: var(--color-on-primary);
  padding: var(--spacing-sm) var(--spacing-lg);
  text-decoration: none;
  font-weight: bold;
  border-radius: 4px;
  transition: opacity 0.2s;
}

.btn-primary:hover {
  opacity: 0.9;
}

/* Sections */
section {
  padding: var(--spacing-xl) 0;
}

/* Grid */
.product-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(250px, 1fr));
  gap: var(--spacing-lg);
  list-style: none;
  padding: 0;
  margin: 0;
}

/* Product Card */
.product-card {
  background-color: var(--color-surface);
  border-radius: 8px;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  transition: transform 0.2s;
  border: 1px solid var(--color-border);
}

.product-card:hover {
  transform: translateY(-4px);
}

.product-image {
  width: 100%;
  height: 200px;
  object-fit: cover;
  background-color: #333;
}

.product-info {
  padding: var(--spacing-md);
  flex-grow: 1;
  display: flex;
  flex-direction: column;
}

.product-card h3 {
  margin-bottom: var(--spacing-xs);
}

.product-card h3 a {
  color: inherit;
  text-decoration: none;
}

.product-card h3 a:focus {
  outline: 2px solid var(--color-primary);
  outline-offset: 4px;
}

.price {
  font-size: 1.25rem;
  font-weight: bold;
  color: var(--color-secondary);
  margin-bottom: var(--spacing-md);
}

.deal-badge {
  background-color: var(--color-error);
  color: #fff;
  padding: 2px 8px;
  border-radius: 4px;
  font-size: 0.875rem;
  font-weight: bold;
  margin-bottom: var(--spacing-sm);
  align-self: flex-start;
}

.btn-add-to-cart {
  width: 100%;
  padding: var(--spacing-sm);
  background: none;
  border: 1px solid var(--color-primary);
  color: var(--color-primary);
  font-weight: bold;
  cursor: pointer;
  border-radius: 4px;
  transition: all 0.2s;
}

.btn-add-to-cart:hover {
  background-color: var(--color-primary);
  color: var(--color-on-primary);
}

/* Footer */
footer {
  background-color: var(--color-surface);
  border-top: 1px solid var(--color-border);
  padding: var(--spacing-xl) 0;
  margin-top: var(--spacing-xl);
}

.footer-content {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: var(--spacing-xl);
}

.footer-section h4 {
  margin-bottom: var(--spacing-md);
}

.footer-links {
  list-style: none;
  padding: 0;
  margin: 0;
}

.footer-links li {
  margin-bottom: var(--spacing-sm);
}

.footer-links a {
  color: var(--color-text-muted);
  text-decoration: none;
}

.footer-links a:hover {
  color: var(--color-primary);
}

/* Responsive */
@media (max-width: 768px) {
  header .container {
    flex-direction: column;
    align-items: flex-start;
  }

  nav[aria-label="Primary"] ul {
    margin-top: var(--spacing-md);
  }

  .hero h1 {
    font-size: 2rem;
  }
}

/* Focus states */
:focus-visible {
  outline: 2px solid var(--color-focus);
  outline-offset: 2px;
}

/* Forced Colors */
@media (forced-colors: active) {
  .btn-primary, .btn-add-to-cart {
