       <h3><a href="/product/${product.id}">${product.name}</a></h3>
       <p class="price">${product.price} ${product.originalPrice ? `<span style="text-decoration: line-through; color: var(--color-text-muted); font-size: 0.9rem; margin-left: var(--spacing-sm);">${product.originalPrice}</span>` : ''}</p>
       <button type="button" class="btn-add-to-cart" aria-label="Add to cart: ${product.name}">Add to Cart</button>
     </div>
   </li>
 `;

